UI_HTML = r"""<!doctype html>
<html lang="ru">
<head>
  <meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1">
  <meta name="theme-color" content="#f6f8fb"><title>Онлайн-деканат — проверка документов</title>
  <style>
    :root{color-scheme:light;--ink:#172a3a;--muted:#6e7e8c;--line:#e4eaf0;--paper:#fff;--bg:#f4f7fa;--blue:#176b87;--blue-dark:#0e526b;--mint:#dff3ec;--shadow:0 24px 70px #18334912}
    [data-theme="dark"]{color-scheme:dark;--ink:#e8f0f5;--muted:#9fb0bb;--line:#30434f;--paper:#17252f;--bg:#0d171e;--blue:#52b5ca;--blue-dark:#2d8ca5;--mint:#18372f;--shadow:0 24px 70px #00000042}[data-theme="dark"] body{background:radial-gradient(ellipse at 10% 0,#173946 0,transparent 34%),var(--bg)}[data-theme="dark"] .topbar{background:#12202ad9;border-color:var(--line)}[data-theme="dark"] .input,[data-theme="dark"] select,[data-theme="dark"] textarea{background:#14232d;color:var(--ink);border-color:#3a515e}[data-theme="dark"] .upload{background:#13232c;border-color:#3a515e}[data-theme="dark"] .field-result,[data-theme="dark"] details pre{background:#12212a}[data-theme="dark"] .placeholder-icon,[data-theme="dark"] .step{background:#193944}[data-theme="dark"] .answer{background:#17372f;border-color:#285f50}[data-theme="dark"] .answer.no-answer{background:#1b2932;border-color:var(--line)}[data-theme="dark"] .source{background:#183943;color:#8fd6e2}[data-theme="dark"] .error{background:#402828;color:#ffb5b5}*{box-sizing:border-box}body{margin:0;background:radial-gradient(ellipse at 10% 0,#e8f4f4 0,transparent 34%),var(--bg);color:var(--ink);font:15px/1.55 "Segoe UI",system-ui,-apple-system,sans-serif;min-height:100vh}
    .topbar{height:76px;border-bottom:1px solid #e8edf1;background:#ffffffd9;display:flex;align-items:center}.topbar-inner{width:min(1120px,calc(100% - 40px));margin:auto;display:flex;align-items:center;justify-content:space-between}
    .brand{display:flex;gap:12px;align-items:center;font-weight:750;letter-spacing:-.02em}.brand-mark{width:38px;height:38px;border-radius:12px;background:var(--blue);color:white;display:grid;place-items:center;font-size:19px;box-shadow:0 7px 15px #176b8729}.brand small{display:block;color:var(--muted);font-size:11px;font-weight:600;letter-spacing:.09em;text-transform:uppercase}
    .local-pill{display:flex;align-items:center;gap:8px;color:#527064;font-size:13px;font-weight:650}.theme-toggle{border:1px solid var(--line);background:transparent;color:var(--ink);border-radius:9px;padding:7px 10px;cursor:pointer;font:inherit;font-size:12px;margin-left:16px}.dot{width:8px;height:8px;border-radius:50%;background:#31a779;box-shadow:0 0 0 4px #31a7791d}
    main{width:min(1120px,calc(100% - 40px));margin:54px auto 70px}.intro{max-width:740px;margin-bottom:30px}.kicker{color:var(--blue);font-size:12px;font-weight:750;letter-spacing:.13em;text-transform:uppercase}.intro h1{font-size:clamp(30px,4.4vw,47px);line-height:1.12;letter-spacing:-.045em;margin:9px 0 12px}.intro p{font-size:16px;color:var(--muted);margin:0;max-width:650px}
    .workspace{display:grid;grid-template-columns:minmax(0,1fr) minmax(350px,.88fr);gap:22px;align-items:start}.card{background:var(--paper);border:1px solid var(--line);border-radius:20px;box-shadow:var(--shadow)}.form-card{padding:28px}.card-heading{display:flex;align-items:flex-start;gap:13px;margin-bottom:23px}.step{flex:0 0 34px;height:34px;border-radius:11px;background:#eaf4f6;color:var(--blue);display:grid;place-items:center;font-weight:800}.card-heading h2{font-size:18px;letter-spacing:-.02em;margin:0 0 3px}.card-heading p{margin:0;color:var(--muted);font-size:13px}
    form{display:grid;gap:18px}.field{display:grid;gap:7px}.field label{font-size:13px;font-weight:700}.field-note{font-size:12px;color:#8995a1}.input,select,textarea{width:100%;border:1px solid #dbe3e9;background:#fff;color:var(--ink);border-radius:11px;padding:12px 13px;font:inherit;transition:border .18s,box-shadow .18s}.input:focus,select:focus,textarea:focus{outline:0;border-color:#65a6b7;box-shadow:0 0 0 4px #176b8712}textarea{min-height:98px;resize:vertical;line-height:1.5}.select-row{display:grid;grid-template-columns:1fr 1fr;gap:13px}.upload{border:1.5px dashed #bdcdd6;background:#f9fbfc;padding:17px;display:flex;align-items:center;gap:13px;cursor:pointer;transition:.18s}.upload:hover,.upload.drag{border-color:var(--blue);background:#f2f9fa}.upload-icon{width:42px;height:42px;border-radius:12px;background:#e8f3f4;color:var(--blue);display:grid;place-items:center;font-size:20px;flex:none}.upload-text{min-width:0}.upload-text strong{font-size:13px;display:block;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.upload-text span{color:var(--muted);font-size:12px}.upload input{position:absolute;width:1px;height:1px;opacity:0;pointer-events:none}
    .submit{border:0;border-radius:11px;background:var(--blue);color:#fff;padding:13px 18px;font:700 14px inherit;font-family:inherit;font-size:14px;font-weight:750;cursor:pointer;box-shadow:0 8px 18px #176b872c;transition:background .18s,transform .18s}.submit:hover{background:var(--blue-dark);transform:translateY(-1px)}.submit:disabled{opacity:.65;cursor:wait;transform:none}.privacy{display:flex;gap:8px;align-items:center;color:#74838e;font-size:12px}.privacy span{color:#31a779}
    .result-card{min-height:450px;overflow:hidden}.result-head{padding:24px 25px 17px;border-bottom:1px solid var(--line);display:flex;justify-content:space-between;align-items:center}.result-head h2{font-size:17px;margin:0;letter-spacing:-.02em}.result-head small{color:var(--muted);font-size:12px}.result-body{padding:22px 25px}.placeholder{min-height:355px;display:flex;flex-direction:column;align-items:center;justify-content:center;text-align:center;color:var(--muted);padding:28px}.placeholder-icon{width:62px;height:62px;border-radius:20px;background:#eef5f5;display:grid;place-items:center;font-size:25px;margin-bottom:15px;color:var(--blue)}.placeholder strong{color:var(--ink);font-size:14px;margin-bottom:5px}.placeholder p{margin:0;max-width:250px;font-size:13px}
    .answer{border-radius:13px;background:#f1f8f5;border:1px solid #d9eee5;padding:16px;margin-bottom:19px}.answer.no-answer{background:#f5f7f9;border-color:var(--line)}.answer-label{font-size:11px;text-transform:uppercase;letter-spacing:.09em;color:#46816b;font-weight:800;margin-bottom:5px}.answer.no-answer .answer-label{color:var(--muted)}.answer-text{font-size:14px;font-weight:600;line-height:1.55}.section-label{font-size:11px;letter-spacing:.1em;text-transform:uppercase;color:#8795a0;font-weight:800;margin:19px 0 9px}.doc-label{font-size:13px;font-weight:700;margin-bottom:9px}.fields{display:grid;gap:7px}.field-result{display:flex;justify-content:space-between;gap:14px;padding:9px 11px;border-radius:9px;background:#f7f9fa;font-size:12px}.field-result span{color:var(--muted)}.field-result strong{text-align:right;font-weight:650;max-width:60%;overflow-wrap:anywhere}.field-result .missing{color:#b07836}.sources{display:flex;flex-wrap:wrap;gap:7px}.source{font-size:11px;color:#28677c;background:#edf6f8;border-radius:7px;padding:5px 8px}details{margin-top:17px;border-top:1px solid var(--line);padding-top:13px}summary{cursor:pointer;color:var(--muted);font-size:12px;font-weight:700}details pre{white-space:pre-wrap;overflow-wrap:anywhere;background:#f7f9fa;padding:12px;border-radius:9px;font:12px/1.5 ui-monospace,Consolas,monospace;max-height:220px;overflow:auto}.error{color:#a13f3f;background:#fff3f1;padding:12px;border-radius:10px;font-size:13px}
    .zoomable-image{cursor:zoom-in}.image-zoom{position:fixed;inset:0;z-index:20;background:#07111de8;display:flex;align-items:center;justify-content:center;padding:4vh 4vw;cursor:zoom-out}.image-zoom img{max-width:100%;max-height:100%;object-fit:contain;box-shadow:0 18px 70px #0009;cursor:default}.image-zoom button{position:absolute;top:18px;right:22px;border:1px solid #ffffff55;border-radius:50%;width:42px;height:42px;background:#142534;color:#fff;font-size:25px;cursor:pointer}
    @media(max-width:830px){main{margin-top:38px}.workspace{grid-template-columns:1fr}.result-card{min-height:300px}.placeholder{min-height:220px}}@media(max-width:540px){.topbar{height:64px}.topbar-inner,main{width:calc(100% - 28px)}main{margin-top:30px}.local-pill{font-size:0}.local-pill .dot{font-size:initial}.form-card{padding:20px}.result-head,.result-body{padding-left:19px;padding-right:19px}.select-row{grid-template-columns:1fr;gap:12px}.intro p{font-size:14px}}
  </style>
</head>
<body>
  <header class="topbar"><div class="topbar-inner"><div class="brand"><div class="brand-mark">О</div><div><small>Студенческий сервис</small>Онлайн-деканат</div></div><div class="local-pill"><span class="dot"></span>Локальная обработка<button class="theme-toggle" id="theme-toggle" type="button" aria-label="Переключить тему">◐ Тема</button></div></div></header>
  <main>
    <section class="intro"><div class="kicker">Помощник по документам</div><h1>Проверьте документ<br>и получите понятный ответ</h1><p>Загрузите фото или скан. Сервис распознает поля и сверит их с требованиями Положения.</p></section>
    <div class="workspace">
      <section class="card form-card"><div class="card-heading"><div class="step">01</div><div><h2>Данные документа</h2><p>Выберите файл и задайте вопрос</p></div></div>
        <form id="form">
          <div class="field"><label for="file">Файл документа</label><label class="upload" id="dropzone" for="file"><span class="upload-icon">↑</span><span class="upload-text"><strong id="file-name">Нажмите, чтобы выбрать файл</strong><span id="file-hint">JPG, PNG, WEBP или PDF · до 20 МБ</span></span><input id="file" name="file" type="file" accept=".jpg,.jpeg,.png,.webp,.bmp,.tif,.tiff,.pdf" required></label></div>
          <div id="upload-preview-wrap" hidden><img id="upload-preview" class="zoomable-image" alt="Предпросмотр выбранного снимка" style="max-width:100%;max-height:260px;object-fit:contain;border-radius:10px"></div>
          <div class="field"><label for="question">Ваш вопрос</label><textarea class="input" id="question" name="question" required>Хватит ли документа для перевода на 2 курс?</textarea></div>
          <div class="privacy"><span>✦</span>Тип документа и способ распознавания определяются автоматически</div>
          <button class="submit" id="submit" type="submit">Проверить документ <span aria-hidden="true">→</span></button><div class="privacy"><span>●</span>Документ обрабатывается локально</div>
        </form>
      </section>
      <section class="card result-card"><div class="result-head"><h2>Результат проверки</h2><small id="result-status">Ожидает документ</small></div><div class="result-body" id="out"><div class="placeholder"><div class="placeholder-icon">▤</div><strong>Здесь появится результат</strong><p>Карточка полей и ответ по требованиям Положения</p></div></div></section>
    </div>
  </main>
  <script>
    const form=document.querySelector("#form"),out=document.querySelector("#out"),themeToggle=document.querySelector("#theme-toggle"),file=document.querySelector("#file"),fileName=document.querySelector("#file-name"),fileHint=document.querySelector("#file-hint"),submit=document.querySelector("#submit"),status=document.querySelector("#result-status"),dropzone=document.querySelector("#dropzone");
    const esc=value=>String(value??"").replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]));
    const savedTheme=localStorage.getItem("online-dekanat-theme");if(savedTheme)document.documentElement.dataset.theme=savedTheme;themeToggle.addEventListener("click",()=>{const next=document.documentElement.dataset.theme==="dark"?"light":"dark";document.documentElement.dataset.theme=next;localStorage.setItem("online-dekanat-theme",next)});
    let uploadUrl=null;file.addEventListener("change",()=>{const f=file.files[0];if(uploadUrl)URL.revokeObjectURL(uploadUrl);uploadUrl=null;const preview=document.querySelector("#upload-preview-wrap"),image=document.querySelector("#upload-preview");preview.hidden=true;if(f){fileName.textContent=f.name;fileHint.textContent=(f.size/1024/1024).toFixed(2)+" МБ";if(f.type.startsWith("image/")){uploadUrl=URL.createObjectURL(f);image.src=uploadUrl;preview.hidden=false}}});
    for(const event of ["dragenter","dragover"])dropzone.addEventListener(event,e=>{e.preventDefault();dropzone.classList.add("drag")});for(const event of ["dragleave","drop"])dropzone.addEventListener(event,e=>{e.preventDefault();dropzone.classList.remove("drag")});dropzone.addEventListener("drop",e=>{if(e.dataTransfer.files.length){file.files=e.dataTransfer.files;file.dispatchEvent(new Event("change"))}});
    function render(data){if(data.error){out.innerHTML='<div class="error">'+esc(data.error)+'</div>';return}const card=data.card||{},answer=data.answer||{},quality=data.quality||{},fields=Object.values(card.fields||{});const rows=fields.map(f=>'<div class="field-result"><span>'+esc(f.title)+'</span><strong class="'+(f.value==="не найдено"?"missing":"")+'">'+esc(f.value)+'</strong></div>').join("");const sources=(answer.sources||[]).map(s=>'<span class="source">'+esc(s)+'</span>').join("");const issues=(quality.issues||[]).join(', ');const qualityText=quality.status==="not_applicable"?"Не требуется для текстового файла":quality.status==="good"?"Хорошее качество снимка":quality.status==="warning"?"Есть проблемы: "+issues:"Плохое качество снимка: "+issues;const qualityBlock='<div class="section-label">Качество снимка</div><div class="field-result"><span>'+esc(qualityText)+'</span><strong>'+esc(String(Math.round((quality.score||0)*100)))+'%</strong></div>';const images=(data.highlights||[]).map(p=>'/highlights/'+encodeURIComponent(String(p).split(/[\\\\/]/).pop())).map(p=>'<img src="'+p+'" class="zoomable-image highlight-image" alt="Подсветка полей карточки" title="Нажмите, чтобы увеличить" style="max-width:100%;border-radius:10px;margin-top:8px">').join('');out.innerHTML='<div class="answer '+(answer.confidence==="no-answer"?"no-answer":"")+'"><div class="answer-label">'+(answer.confidence==="no-answer"?"Нет данных":"Ответ по Положению")+'</div><div class="answer-text">'+esc(answer.text)+'</div></div>'+qualityBlock+(images?'<div class="section-label">Фрагменты, использованные в карточке · нажмите, чтобы увеличить</div>'+images:'')+'<div class="section-label">Карточка документа</div><div class="doc-label">'+esc(card.doc_label||"Документ")+'</div><div class="fields">'+rows+'</div><div class="section-label">Источники</div><div class="sources">'+sources+'</div><details><summary>Распознанный текст</summary><pre>'+esc(card.raw_text||"")+'</pre></details>';}
    out.addEventListener("click",e=>{const thumbnail=e.target.closest(".zoomable-image");if(!thumbnail)return;const overlay=document.createElement("div");overlay.className="image-zoom";overlay.innerHTML='<button type="button" aria-label="Закрыть">×</button><img alt="Увеличенная подсветка фрагментов">';overlay.querySelector("img").src=thumbnail.src;const close=()=>overlay.remove();overlay.addEventListener("click",e=>{if(e.target===overlay||e.target.tagName==="BUTTON")close()});document.body.appendChild(overlay);const onKey=e=>{if(e.key==="Escape"){close();document.removeEventListener("keydown",onKey)}};document.addEventListener("keydown",onKey)});
    form.addEventListener("submit",async e=>{e.preventDefault();submit.disabled=true;submit.textContent="Распознаём документ…";status.textContent="Обработка";out.innerHTML='<div class="placeholder"><div class="placeholder-icon">…</div><strong>Анализируем документ</strong><p>Первая загрузка модели может занять несколько минут</p></div>';try{const response=await fetch("/process",{method:"POST",body:new FormData(form)});const raw=await response.text();let data;try{data=raw?JSON.parse(raw):{}}catch(_){data={error:"Сервер вернул некорректный ответ (HTTP "+response.status+")"}}if(!response.ok&&!data.error)data.error="Не удалось обработать документ";render(data);status.textContent=data.error?"Не удалось обработать":"Готово"}catch(error){out.innerHTML='<div class="error">Не удалось связаться с сервером: '+esc(error.message)+'</div>';status.textContent="Ошибка"}finally{submit.disabled=false;submit.innerHTML='Проверить документ <span aria-hidden="true">→</span>'}});
  </script>
</body></html>"""